test('invoiceTotals: with actual invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 8 * 9500 + 5 * 8500);
